import{_ as a,o as e,c as s,a5 as r}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"UEのスマートポインタ — TSharedPtr・TUniquePtr・TWeakPtr・TSoftObjectPtr","description":"","frontmatter":{"title":"UEのスマートポインタ — TSharedPtr・TUniquePtr・TWeakPtr・TSoftObjectPtr","study":{"source":"C++ Wiki","status":"published","summary":"UEは標準の std::shared_ptr 等を使わず、同じ概念の独自実装(TSharedPtr等)を持ちます。使い分けの考え方は標準スマートポインタと同一で、適用対象が「非UObject」に限られる点だけがUE特有の重要ルールです。","section":"reference","format":"article","domain":"game"}},"headers":[],"relativePath":"game/unreal/smart-pointers.md","filePath":"game/unreal/smart-pointers.md"}'),n={name:"game/unreal/smart-pointers.md"};function i(l,t,d,o,h,p){return e(),s("div",null,[...t[0]||(t[0]=[r(`<h1 id="ueのスマートポインタ-—-tsharedptr・tuniqueptr・tweakptr・tsoftobjectptr" tabindex="-1">UEのスマートポインタ — TSharedPtr・TUniquePtr・TWeakPtr・TSoftObjectPtr <a class="header-anchor" href="#ueのスマートポインタ-—-tsharedptr・tuniqueptr・tweakptr・tsoftobjectptr" aria-label="Permalink to &quot;UEのスマートポインタ — TSharedPtr・TUniquePtr・TWeakPtr・TSoftObjectPtr&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>UEは標準の <code>std::shared_ptr</code> 等を使わず、<strong>同じ概念の独自実装</strong>(TSharedPtr等)を持ちます。使い分けの考え方は<a href="/study/languages/cpp/smart-pointers.html">標準スマートポインタ</a>と同一で、<strong>適用対象が「非UObject」に限られる</strong>点だけがUE特有の重要ルールです。</p><h2 id="対応表" tabindex="-1">対応表 <a class="header-anchor" href="#対応表" aria-label="Permalink to &quot;対応表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>標準C++</th><th>UE(非UObject用)</th><th>UObject用(→ <a href="/study/game/unreal/gc-and-object-pointers.html">GCページ</a>)</th></tr></thead><tbody><tr><td><code>std::unique_ptr&lt;T&gt;</code></td><td><code>TUniquePtr&lt;T&gt;</code></td><td>(対応なし — GCが管理)</td></tr><tr><td><code>std::shared_ptr&lt;T&gt;</code></td><td><code>TSharedPtr&lt;T&gt;</code> / <code>TSharedRef&lt;T&gt;</code>(null非許容版)</td><td><code>UPROPERTY() TObjectPtr&lt;T&gt;</code></td></tr><tr><td><code>std::weak_ptr&lt;T&gt;</code></td><td><code>TWeakPtr&lt;T&gt;</code></td><td><code>TWeakObjectPtr&lt;T&gt;</code></td></tr><tr><td><code>std::make_shared</code></td><td><code>MakeShared&lt;T&gt;()</code> / <code>MakeShareable</code></td><td><code>NewObject&lt;T&gt;()</code></td></tr><tr><td>(遅延ロードの概念なし)</td><td>—</td><td><code>TSoftObjectPtr&lt;T&gt;</code>(パス保持・要求時ロード → <a href="/study/design/patterns/proxy.html">Proxy</a>)</td></tr></tbody></table><p><strong>鉄則: UObjectに標準/TSharedPtrを使わない。非UObjectにTObjectPtrは使えない。</strong> 2つの管理系(<a href="/study/runtime/memory/gc-and-csharp-comparison.html">GCとRAII</a>)を型で混ぜないことがUE C++の秩序です。</p><h2 id="なぜ独自実装なのか" tabindex="-1">なぜ独自実装なのか <a class="header-anchor" href="#なぜ独自実装なのか" aria-label="Permalink to &quot;なぜ独自実装なのか&quot;">​</a></h2><ol><li><strong>歴史</strong>: UEのコードベースはC++11(std::shared_ptr標準化)より古く、独自実装が先にあった</li><li><strong>制御</strong>: スレッドセーフモードの選択(<code>ESPMode</code>)、エンジンのアロケータ・診断との統合、公開する型や実装をUE側の規約にそろえられる。ただしUE独自型でも、コンパイラ・対象CPU・エンジン版・ビルド設定などの<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">ABI</a>互換条件がなくなるわけではない</li><li>コンテナ(TArray/FString)も同じ理由で独自——「標準が悪いから」ではなく「<strong>エンジンが全プラットフォームで同一の挙動とメモリ管理を保証したいから</strong>」。この動機は<a href="/study/languages/cpp/stl.html">EASTLなど他エンジン系STL</a>と共通</li></ol><h2 id="tsharedref-標準にない良いもの" tabindex="-1">TSharedRef(標準にない良いもの) <a class="header-anchor" href="#tsharedref-標準にない良いもの" aria-label="Permalink to &quot;TSharedRef(標準にない良いもの)&quot;">​</a></h2><p><code>TSharedRef&lt;T&gt;</code> は<strong>nullになれないshared参照</strong>。「必ず存在する」を型で表現でき(<a href="/study/languages/cpp/values-pointers-references.html">参照のnull非許容性</a>と同じ発想)、APIの契約が明確になります。標準C++に相当物がなく、UEから輸入したくなる設計です。</p><h2 id="tsoftobjectptr-アセット参照の要" tabindex="-1">TSoftObjectPtr(アセット参照の要) <a class="header-anchor" href="#tsoftobjectptr-アセット参照の要" aria-label="Permalink to &quot;TSoftObjectPtr(アセット参照の要)&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UPROPERTY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EditAnywhere)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TSoftObjectPtr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UStaticMesh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HeavyMesh;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // エディタではアセットを「パス」で指す(ロードしない)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 使うとき明示的にロード(同期/非同期)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UStaticMesh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Mesh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HeavyMesh.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LoadSynchronous</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            // または StreamableManagerで非同期</span></span></code></pre></div><ul><li><strong>ハード参照(TObjectPtr)の連鎖はロードの連鎖</strong>: あるActorをロードすると、そのUPROPERTYが指すアセットも芋づるでロードされる。ソフト参照はこの連鎖を切る道具——<a href="/study/design/patterns/proxy.html">Proxy/遅延ロード</a>と<a href="/study/game/patterns/optimization-patterns.html">アセット管理</a>の実践形</li><li>Unity対応: <code>AssetReference</code>(Addressables)とほぼ同じ役割</li></ul><h2 id="使い分けフローチャート-ue版" tabindex="-1">使い分けフローチャート(UE版) <a class="header-anchor" href="#使い分けフローチャート-ue版" aria-label="Permalink to &quot;使い分けフローチャート(UE版)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>管理したいのは UObject 系?</span></span>
<span class="line"><span> ├ Yes → メンバ保存: UPROPERTY() TObjectPtr&lt;T&gt;</span></span>
<span class="line"><span> │        消えるかもしれない相手: TWeakObjectPtr&lt;T&gt;</span></span>
<span class="line"><span> │        アセットで、ロード時期を制御したい: TSoftObjectPtr&lt;T&gt;</span></span>
<span class="line"><span> └ No(純C++クラス、Slateウィジェット等)</span></span>
<span class="line"><span>          → 所有1人: TUniquePtr (第一候補)</span></span>
<span class="line"><span>            共有が本当に必要: TSharedPtr(/TSharedRef)</span></span>
<span class="line"><span>            循環切り・観測: TWeakPtr</span></span></code></pre></div><p>判断の考え方は<a href="/study/design/decisions/cpp-choices.html">unique_ptrかshared_ptrか</a>がそのまま適用できます。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「スマートポインタは1種類覚えればいい」— UEでは<strong>UObject系と非UObject系の2系統</strong>を必ず区別する</li><li>SlateのUI(SWidget)はTSharedPtrの世界(UObjectではない)——UMG(UObject)とSlateで管理系が変わる(→ <a href="/study/game/unreal/gameplay-framework.html">Gameplay Framework</a>)</li><li><code>TSoftObjectPtr</code>を「弱参照の一種」と混同——弱参照(生死の観測)ではなく<strong>ロード制御</strong>(パス参照)。目的が違う</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>UObjectと非UObjectでポインタの選択肢がどう分かれますか。</li><li>UEが標準スマートポインタを使わない理由を2つ挙げてください。</li><li>ハード参照とソフト参照の違いは何に効きますか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>「ボス戦アセット(巨大)を、ボス部屋の手前で先読みし、戦闘後に解放する」フローを、TSoftObjectPtr+非同期ロードの擬似コードで設計してください。Unity Addressablesで同じことを書いた場合との対応も書き添えてください。</p><hr><p>関連項目：<a href="/study/game/unreal/build-system-ubt.html">UBT・Module・Build.cs</a> | <a href="/study/game/unreal/">この分野の学習ガイド</a> | <a href="/study/game/unreal/delegates-and-interfaces.html">UEのDelegateとInterface</a></p>`,24)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
